import java.util.*;import java.math.*;import org.json.*;import catdata.*;import catdata.cql.*;import catdata.cql.exp.*;
/** Structured finite instance adapter. No import/export/file/JDBC expressions. */
final class DataEvaluator {
 final SchemaCompiler s,t;final JSONObject data;final Map<String,List<JSONObject>> rows=new LinkedHashMap<>();final Map<String,List<String>> gens=new LinkedHashMap<>();final JSONObject identityManifest=new JSONObject();
 DataEvaluator(SchemaCompiler source,SchemaCompiler target,JSONObject d){s=source;t=target;data=d;SchemaCompiler.checkKeys(d,Set.of("tables"));JSONObject tables=d.getJSONObject("tables");for(String en:tables.keySet())s.entity(en);int serial=0;for(String en:s.tables.keySet()){if(!tables.has(en))throw new IllegalArgumentException("Missing input table "+en);JSONArray pk=s.tables.get(en).getJSONArray("primaryKey");if(pk.isEmpty())throw new UnsupportedOperationException("Source table requires explicit native primaryKey: "+en);List<JSONObject> rs=new ArrayList<>();List<String> gs=new ArrayList<>();Set<String> keys=new HashSet<>();JSONArray manifest=new JSONArray();for(Object o:tables.getJSONArray(en)){JSONObject input=(JSONObject)o,row=new JSONObject();for(String c:input.keySet())s.findColumn(en,c);for(Object co:s.tables.get(en).getJSONArray("columns")){JSONObject c=(JSONObject)co;String id=c.getString("id");if(!input.has(id)||input.isNull(id))throw new UnsupportedOperationException("Null/missing scalar has no supported semantics: "+en+"."+id);row.put(id,canonical(c,input.get(id)));}String key=key(row,pk);if(!keys.add(key))throw new IllegalArgumentException("Duplicate native primary key: "+en);String gen="g"+(serial++);gs.add(gen);rs.add(row);manifest.put(new JSONObject().put("primaryKey",new JSONArray(key)).put("generator",gen));}rows.put(en,rs);gens.put(en,gs);identityManifest.put(en,manifest);}}
 static void requireTargetKeyTransport(SchemaCompiler target){for(String en:target.tables.keySet())for(Object key:target.tables.get(en).getJSONArray("primaryKey")){JSONObject col=target.findColumn(en,(String)key);if(!col.has("generated")&&!target.columns.get(en).containsKey((String)key))throw new UnsupportedOperationException("Missing explicit target key transport: "+en+"."+key+"; hidden business keys require a bound recipe target attribute");}}
 static Object canonical(JSONObject col,Object value){String ty=SchemaCompiler.type(col);if(ty.equals("Bool")){if(value instanceof Boolean)return value;if(value.equals("true"))return true;if(value.equals("false"))return false;throw new IllegalArgumentException("Bool requires true or false");}if(!(value instanceof String))throw new IllegalArgumentException("Text/integer/real input must be strings to preserve precision");String v=(String)value;return switch(ty){case "Text"->v;case "Integer"->{if(!v.matches("-?(0|[1-9][0-9]*)"))throw new IllegalArgumentException("Invalid Int64 lexical value");yield Long.toString(Long.parseLong(v));}case "exactReal"->{if(!v.matches("[+-]?(?:[0-9]+(?:[.][0-9]*)?|[.][0-9]+)"))throw new IllegalArgumentException("Invalid exactReal lexical value");yield new BigDecimal(v).toPlainString();}default->throw new IllegalArgumentException("Unsupported type");};}
 static String key(JSONObject row,JSONArray cols){JSONArray a=new JSONArray();for(Object c:cols)a.put(row.get((String)c));return a.toString();}
 String sourceLiteral(String instanceName,String schemaName,boolean algebra){StringBuilder b=new StringBuilder("instance "+instanceName+" = literal : "+schemaName+" {\ngenerators\n");for(String en:rows.keySet())for(String g:gens.get(en))b.append(g).append(" : ").append(s.entity(en)).append('\n');b.append("equations\n");for(String en:rows.keySet()){List<JSONObject> rs=rows.get(en);for(int i=0;i<rs.size();i++){JSONObject row=rs.get(i);String g=gens.get(en).get(i);for(var c:s.columns.get(en).entrySet())b.append(g).append('.').append(c.getValue()).append(" = ").append(JSONObject.quote(row.get(c.getKey()).toString())).append('\n');for(Object fo:s.foreignKeys(en)){JSONObject f=(JSONObject)fo;String dest=s.fkTarget(f),needle=key(row,f.getJSONArray("source_columns"));String hit=null;for(int k=0;k<rows.get(dest).size();k++)if(needle.equals(key(rows.get(dest).get(k),f.getJSONArray("target_columns")))){if(hit!=null)throw new IllegalArgumentException("Ambiguous FK target "+f.getString("id"));hit=gens.get(dest).get(k);}if(hit==null)throw new IllegalArgumentException("Unresolved FK "+f.getString("id")+" at "+g);b.append(g).append('.').append(s.fks.get(en).get(f.getString("id"))).append(" = ").append(hit).append('\n');}}}return b.append(algebra?"options interpret_as_algebra = true\n}\n":"}\n").toString();}
 String instance(){return sourceLiteral("Input","S",false)+"instance Result = eval Q Input\n";}
 @SuppressWarnings({"rawtypes","unchecked"}) JSONObject result(Instance instance){requireTargetKeyTransport(t);Map<String,Map<Object,String>> ids=new LinkedHashMap<>();for(String en:t.tables.keySet()){Map<Object,String> m=new HashMap<>();int n=0;for(Object row:instance.algebra().en(t.entity(en)))m.put(row,"r"+(n++));ids.put(en,m);}JSONObject tables=new JSONObject();for(String en:t.tables.keySet()){JSONArray output=new JSONArray();for(Object row:instance.algebra().en(t.entity(en))){JSONObject values=new JSONObject(),fks=new JSONObject();for(Object att:instance.schema().attsFrom(t.entity(en))){String nativeId=null;for(var c:t.columns.get(en).entrySet())if(c.getValue().equals(att.toString()))nativeId=c.getKey();Object value=instance.algebra().att(att,row).obj();if(value==null)throw new UnsupportedOperationException("Unevaluated target scalar");values.put(nativeId,canonical(t.findColumn(en,nativeId),value instanceof Boolean?value:value.toString()));}for(Object fk:instance.schema().fksFrom(t.entity(en))){String nativeId=null,dest=null;for(Object fo:t.foreignKeys(en)){JSONObject f=(JSONObject)fo;if(t.fks.get(en).get(f.getString("id")).equals(fk.toString())){nativeId=f.getString("id");dest=t.fkTarget(f);}}String target=ids.get(dest).get(instance.algebra().fk(fk,row));if(target==null)throw new IllegalStateException("CQL FK output unresolved");fks.put(nativeId,target);}output.put(new JSONObject().put("id",ids.get(en).get(row)).put("values",values).put("foreignKeys",fks));}tables.put(en,output);}return tables;}
 static AqlEnv evaluate(String text)throws Exception{Program<Exp<?>> p=AqlParserFactory.getParser().parseProgram(text);AqlEnv env=new AqlEnv(p);env.typing=new AqlTyping(p,false);for(String n:p.order){Exp<?> e=p.exps.get(n);if(!Set.of(Kind.TYPESIDE,Kind.SCHEMA,Kind.QUERY,Kind.INSTANCE).contains(e.kind()))throw new IllegalArgumentException("Prohibited expression");env.defs.put(n,e.kind(),e.eval(env,false));}return env;}
}
